/* @lc app=leetcode id=3664 lang=kotlin */ class Solution { fun best(s: Int, m: Int, e: Int): Int = if (2 * m > s) minOf(e, 2 * m - s) + (s - m) else s / 2 + minOf(e, s % 2) fun score(cards: Array<String>, x: Char): Int = cards.filter { it[0] == x && it[1] != x }.groupingBy { it[1] }.eachCount().values.let { a -> cards.filter { it[1] == x && it[0] != x }.groupingBy { it[0] }.eachCount().values.let { b -> cards.count { it[0] == x && it[1] == x }.let { e -> (0..e).maxOf { ea -> best(a.sum(), a.maxOrNull() ?: 0, ea) + best(b.sum(), b.maxOrNull() ?: 0, e - ea) } } } } }